#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line); // Read the first line and ignore
    getline(cin, line); // Read the second line

    // Split inputLine by pattern "\([a-zA-Z_]*\)"
    vector<string> splitInput;
    regex pattern("\\([a-zA-Z_]*\\)");
    sregex_token_iterator iter(line.begin(), line.end(), pattern, -1);
    sregex_token_iterator end;
    for (; iter != end; ++iter) {
        splitInput.push_back(iter->str());
    }

    int maxWordLen = 0;
    for (const auto& segment : splitInput) {
        // Split segment by underscores
        stringstream ss(segment);
        string word;
        while (getline(ss, word, '_')) {
            if (!word.empty()) {
                maxWordLen = max(maxWordLen, (int)word.length());
            }
        }
    }

    int parenthesesLetters = 0;
    int countLettersInParentheses = 0;
    bool inParentheses = false;
    bool letterCounted = false;

    for (size_t i = 0; i < line.length(); ++i) {
        char c = line[i];
        if (c == '(') {
            inParentheses = true;
        } else if (c == ')') {
            letterCounted = false;
            inParentheses = false;
        } else if (inParentheses && isalpha(c)) {
            if (letterCounted) continue;
            parenthesesLetters++;
            letterCounted = true;
        } else if (c == '_') {
            letterCounted = false;
        }
    }

    cout << maxWordLen << " " << parenthesesLetters << "\n";

    return 0;
}
